from target import resolve_settings


def test_env_overrides_template():
    assert resolve_settings({"port": "8080"}, {"port": "9090"}) == {"port": "9090"}


def test_empty_env_value_keeps_template_value():
    assert resolve_settings({"port": "8080"}, {"port": ""}) == {"port": "8080"}


def test_empty_everywhere_drops_the_key():
    assert resolve_settings({"port": ""}, {"port": ""}) == {}
